1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export type StepResult =
41	  | { premium: number }
42	  | { payout: number; remainingCap: number };
43	
44	export interface ScenarioResult {
45	  results: StepResult[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	} as const satisfies Record<string, number>;
59	
60	type InsurableItemType = keyof typeof BASE_PREMIUMS;
61	
62	const basePremiumOf = (item: Item): number =>
63	  BASE_PREMIUMS[item.type as InsurableItemType];
64	
65	/** Premiums are rounded up — in MHPCO's favour. */
66	const roundPremium = (amount: number): number => Math.ceil(amount);
67	
68	const COMPONENT_BLOCK_SIZE = 3;
69	const COMPONENT_BLOCK_PREMIUM = 60;
70	
71	/** Items of a single type, kept together so the block rule can be applied. */
72	type SameTypeGroup = Item[];
73	
74	const groupByType = (items: Item[]): SameTypeGroup[] => {
75	  const groups = new Map<string, SameTypeGroup>();
76	  for (const item of items) {
77	    const group = groups.get(item.type) ?? [];
78	    group.push(item);
79	    groups.set(item.type, group);
80	  }
81	  return [...groups.values()];
82	};
83	
84	const sumBasePremiums = (group: SameTypeGroup): number =>
85	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
86	
87	/**
88	 * Exactly three alike items form a building block priced at a flat premium;
89	 * any other count is priced per item.
90	 */
91	const blockAwareBasePremium = (group: SameTypeGroup): number =>
92	  group.length === COMPONENT_BLOCK_SIZE
93	    ? COMPONENT_BLOCK_PREMIUM
94	    : sumBasePremiums(group);
95	
96	const policyBasePremiumFor = (items: Item[]): number =>
97	  groupByType(items).reduce(
98	    (sum, group) => sum + blockAwareBasePremium(group),
99	    0,
100	  );
101	
102	const HIGH_ENCHANTMENT_LEVEL = 5;
103	
104	const isCursed = (item: Item): boolean => item.cursed === true;
105	const isHighlyEnchanted = (item: Item): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
107	
108	/**
109	 * An item-specific surcharge: when the item triggers the clause, it is charged
110	 * a rate of that item's own base premium — never of the whole policy's.
111	 */
112	interface ItemSurcharge {
113	  appliesTo: (item: Item) => boolean;
114	  rate: number;
115	}
116	
117	const ITEM_SURCHARGES: ItemSurcharge[] = [
118	  { appliesTo: isCursed, rate: 0.5 },
119	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
120	];
121	
122	/** Every clause the item triggers stacks, each on that item's base premium. */
123	const surchargeRateFor = (item: Item): number =>
124	  ITEM_SURCHARGES.reduce(
125	    (rate, surcharge) =>
126	      surcharge.appliesTo(item) ? rate + surcharge.rate : rate,
127	    0,
128	  );
129	
130	const itemSurcharges = (items: Item[]): number =>
131	  items.reduce(
132	    (sum, item) => sum + basePremiumOf(item) * surchargeRateFor(item),
133	    0,
134	  );
135	
136	const LOYALTY_DISCOUNT = 0.2;
137	const LOYALTY_YEARS = 2;
138	
139	const isLoyal = (customer: Customer): boolean =>
140	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
141	
142	/** Policy-wide modifiers apply to the sum of all item base premiums. */
143	const loyaltyDiscount = (policyBasePremium: number, customer: Customer): number =>
144	  isLoyal(customer) ? policyBasePremium * LOYALTY_DISCOUNT : 0;
145	
146	const quotePremium = (items: Item[], customer: Customer): number => {
147	  const policyBasePremium = policyBasePremiumFor(items);
148	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
149	  return roundPremium(
150	    policyBasePremium +
151	      itemSurcharges(items) +
152	      firstInsuranceSurcharge -
153	      loyaltyDiscount(policyBasePremium, customer) +
154	      PROCESSING_FEE,
155	  );
156	};
157	
158	const runStep = (step: Step, customer: Customer): StepResult => {
159	  if (step.op === "quote") {
160	    return { premium: quotePremium(step.items, customer) };
161	  }
162	  throw new Error(`Unsupported step: ${step.op}`);
163	};
164	
165	export const runScenario = (scenario: Scenario): ScenarioResult => ({
166	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
167	});
