input.new_string:
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const LOYALTY_DISCOUNT_RATE = -0.2;
const LOYALTY_YEARS = 2;

const isFirstInsurance = (_customer: Customer): boolean => true;
const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

/**
 * A policy-wide modifier: when the customer triggers the clause, the whole
 * policy's base premium is adjusted by that rate — never a single item's.
 * A negative rate is a discount.
 */
interface PolicyModifier {
  appliesTo: (customer: Customer) => boolean;
  rate: number;
}

const POLICY_MODIFIERS: PolicyModifier[] = [
  { appliesTo: isFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  { appliesTo: isLoyal, rate: LOYALTY_DISCOUNT_RATE },
];

/** Every clause the customer triggers stacks on the policy base premium. */
const policyModifierRateFor = (customer: Customer): number =>
  POLICY_MODIFIERS.reduce(
    (rate, modifier) =>
      modifier.appliesTo(customer) ? rate + modifier.rate : rate,
    0,
  );

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBasePremium = policyBasePremiumFor(items);
  return roundPremium(
    policyBasePremium +
      policyBasePremium * policyModifierRateFor(customer) +
      itemSurchargesFor(items) +
      PROCESSING_FEE,
  );
};
